  "test_path": "tests/unit/test_observe_capture_error.py",
  "test": "import pytest
from types import SimpleNamespace
from langfuse._client.observe import observe, get_client

class SpanRecorder:
    def __init__(self):
        self.updates = []
        self.ended = False
    def update(self, **kwargs):
        self.updates.append(kwargs)
        return self
    def end(self):
        self.ended = True
        return self

class DummyContextManager:
    def __init__(self, span):
        self.span = span
    def __enter__(self):
        return self.span
    def __exit__(self, exc_type, exc, tb):
        return False

class DummyClient:
    def __init__(self, span):
        self.span = span
    def start_as_current_observation(self, **kwargs):
        return DummyContextManager(self.span)

def test_observe_records_error_by_default(monkeypatch):
    span = SpanRecorder()
    dummy_client = DummyClient(span)
    monkeypatch.setattr('langfuse._client.observe.get_client', lambda public_key=None: dummy_client)

    @observe(name="error_default")
    def raise_error():
        raise ValueError("boom")

    with pytest.raises(ValueError):
        raise_error()

    # Should have recorded an error update
    assert any(u.get('level') == 'ERROR' for u in span.updates)

def test_observe_suppresses_error_when_capture_error_false(monkeypatch):
    span = SpanRecorder()
    dummy_client = DummyClient(span)
    monkeypatch.setattr('langfuse._client.observe.get_client', lambda public_key=None: dummy_client)

    @observe(name="error_suppressed", capture_error=False)
    def raise_error():
        raise RuntimeError("oops")

    with pytest.raises(RuntimeError):
        raise_error()

    # No error update should be recorded
    assert not any(u.get('level') == 'ERROR' for u in span.updates)
